import hashlib,json,os,subprocess
from pathlib import Path
from genlayer_py import create_account,create_client
from genlayer_py.chains import studionet
R=Path(__file__).parents[1];code=(R/'contracts'/'contract.py').read_text();key=os.environ['GENLAYER_PRIVATE_KEY'];client=create_client(chain=studionet,account=create_account(account_private_key=key));tx=client.deploy_contract(code=code,args=[]);print('deploy_tx='+str(tx),flush=True);receipt=client.wait_for_transaction_receipt(transaction_hash=tx,wait_until='finalized',retries=180,interval=5000,full_transaction=True);leaders=receipt.get('consensus_data',{}).get('leader_receipt') or [];leaders=[leaders] if isinstance(leaders,dict) else leaders;assert receipt.get('result_name')=='MAJORITY_AGREE' and any(x.get('execution_result')=='SUCCESS' for x in leaders);address=receipt.get('data',{}).get('contract_address') or receipt.get('to_address');data={'network':'StudioNet','contractAddress':address,'deploymentTransaction':str(tx),'sourceSha256':hashlib.sha256(code.encode()).hexdigest(),'sourceCommit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip(),'repository':'https://github.com/wakbowaa/counterexample-bell'};(R/'deployment.json').write_text(json.dumps(data,indent=2)+'\n');print(json.dumps(data,indent=2))
